      "sectionId": "chap_tin11_c3_s1",
      "stem": "Khi tắt máy tính đột ngột, Nam phát hiện một văn bản quan trọng đang soạn thảo bị mất. Em hãy giúp Nam chọn ra những nhận định đúng về RAM và ROM:",
